const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};

// TODO vor Produktivbetrieb: Secret aus Umgebungsvariable statt hardcoded (Task-Runner-Sandbox blockiert aktuell $env-Zugriff im Code-Node, siehe Report).
const expected = 'REPLACE_LEAD_WEBHOOK_SECRET';
const provided = headers['x-lead-secret'] || headers['X-Lead-Secret'];

if (!expected || provided !== expected) {
  return [{ json: { ok: false, message: 'unauthorized' } }];
}

const required = ['email', 'branche', 'team', 'engpass', 'heute', 'stunden'];
const missing = required.filter((k) => !body[k]);
if (missing.length) {
  return [{ json: { ok: false, message: 'missing fields: ' + missing.join(', ') } }];
}

const fs = require('fs');
const logPath = '/files/leads_log/leads.jsonl';
const line = JSON.stringify(Object.assign({ received_at: new Date().toISOString() }, body)) + '\n';
fs.appendFileSync(logPath, line);

return [{ json: { ok: true, message: 'lead received' } }];
